/* Tests for src/zigstd/inflate.hpp.
 *
 * Wisp-specific: there is no upstream counterpart. Ghostty uses Zig's
 * std.compress.flate, which this port cannot transliterate, so the inflate is
 * written from RFC 1951 and RFC 1950 and needs its own tests.
 *
 * The vectors below were produced by a reference zlib implementation
 * (CPython's zlib module) at the compression levels noted, so they exercise
 * stored blocks (level 0), fixed Huffman (short inputs), dynamic Huffman, and
 * long back-references -- not just whatever this decoder happens to accept.
 * The malformed cases check that bad input is rejected rather than trusted.
 */

#include <stdint.h>
#include <string.h>

#include "test_helpers.h"
#include "../zigstd/inflate.hpp"

using namespace wisp;
using wisp::zigstd::ArrayListUnmanaged;

static zigstd::Allocator talloc() { return zigstd::testing_allocator(); }

struct ListGuard {
    ArrayListUnmanaged<uint8_t> list;
    ~ListGuard() { list.deinit(talloc()); }
};

/* Inflate `comp` and compare against `plain`. */
static bool roundTrip(const uint8_t *comp, size_t comp_len, const uint8_t *plain,
                      size_t plain_len) {
    ListGuard g;
    if (!zigstd::inflateZlib(talloc(), comp, comp_len, 16 * 1024 * 1024, &g.list)) return false;
    if (g.list.items_len != plain_len) return false;
    return plain_len == 0 || memcmp((const void *)g.list.items, (const void *)plain, plain_len) == 0;
}

/* zlib level 6: 0 bytes in, 8 bytes compressed */
static const uint8_t comp_empty[] = {120,156,3,0,0,0,0,1};
static const size_t comp_empty_len = sizeof(comp_empty);

static const uint8_t plain_empty[1] = {0};
static const size_t plain_empty_len = 0;

TEST(inflate, empty) {
    ASSERT_TRUE(roundTrip(comp_empty, comp_empty_len, plain_empty, plain_empty_len));
}

