static const uint8_t plain_short[] = {104,101,108,108,111,32,119,111,114,108,100};
static const size_t plain_short_len = sizeof(plain_short);

TEST(inflate, short) {
    ASSERT_TRUE(roundTrip(comp_short, comp_short_len, plain_short, plain_short_len));
}

